function extractionInput(body, bucket, enableCalls) {
  if (!enableCalls)
    throw new Error("Verify webhook Header authentication before enabling Gemini calls");
  if (typeof bucket !== "string" || !/^[a-z0-9][a-z0-9._-]{1,220}[a-z0-9]$/.test(bucket)) {
    throw new Error("Configure a Google Cloud Storage bucket");
  }
  const { image_url: imageUrl, Requirement: instruction, properties, required } = body ?? {};
  const match =
    typeof imageUrl === "string" &&
    imageUrl.length <= 4096 &&
    /^https:\/\/storage\.googleapis\.com\/([a-z0-9._-]+)\/([^?\s#\\]+)(?:\?[^\s#\\]*)?$/.exec(
      imageUrl,
    );
  if (
    !match ||
    match[1] !== bucket ||
    match[2].split("/").some((segment) => {
      const decoded = decodeURIComponent(segment);
      return (
        !decoded || decoded === "." || decoded === ".." || /[\/\\%\x00-\x1f\x7f]/.test(decoded)
      );
    })
  )
    throw new Error("The image must be a direct HTTPS object URL in the configured storage bucket");
  if (typeof instruction !== "string" || !instruction.trim() || instruction.length > 4000) {
    throw new Error("Requirement must contain 1 to 4000 characters");
  }
  return {
    imageUrl,
    instruction,
    schema: extractionSchema({ type: "object", properties, required }),
  };
}

function extractionSchema(root) {
  let values = 0;
  function field(node, depth) {
    if (!node || typeof node !== "object" || Array.isArray(node) || ++values > 48 || depth > 5) {
      throw new Error("Invalid or oversized extraction schema");
    }
    const type = typeof node.type === "string" ? node.type.toLowerCase() : "";
    const permitted = ["type", "description", "nullable"];
    if (type === "object") permitted.push("properties", "required");
    else if (type === "array") permitted.push("items");
    else if (["string", "integer", "number"].includes(type)) permitted.push("enum");
    else if (type !== "boolean") throw new Error("Unsupported schema type");
    if (
      Object.keys(node).some((key) => !permitted.includes(key)) ||
      (node.nullable !== undefined && typeof node.nullable !== "boolean") ||
      (node.description !== undefined &&
        (typeof node.description !== "string" || node.description.length > 400))
    ) {
      throw new Error("Unsupported schema keyword or value");
    }
    const converted = { type: node.nullable ? [type, "null"] : type };
    if (node.description !== undefined) converted.description = node.description;
    if (type === "object") {
      const fields = node.properties;
      if (!fields || typeof fields !== "object" || Array.isArray(fields))
        throw new Error("Object schema requires properties");
      const keys = Object.keys(fields);
      if (
        !keys.length ||
        keys.some(
          (key) =>
            !key || key.length > 80 || ["__proto__", "prototype", "constructor"].includes(key),
        )
      ) {
        throw new Error("Invalid property name or missing properties");
      }
      const required = node.required;
      if (
        required !== undefined &&
        (!Array.isArray(required) ||
          new Set(required).size !== required.length ||
          required.some((key) => !keys.includes(key)))
      ) {
        throw new Error("required must list declared property names once each");
      }
      converted.properties = Object.fromEntries(
        keys.map((key) => [key, field(fields[key], depth + 1)]),
      );
      converted.additionalProperties = false;
      if (required !== undefined) converted.required = required;
    } else if (type === "array") {
      converted.items = field(node.items, depth + 1);
    } else if (node.enum !== undefined) {
      if (
        !Array.isArray(node.enum) ||
        !node.enum.length ||
        node.enum.length > 20 ||
        node.enum.some((value) => !extractedValueMatches(value, { type }))
      )
        throw new Error("Invalid enum values");
      converted.enum = node.enum;
    }
    return converted;
  }
  return field(root, 0);
}

function extractedValueMatches(value, schema) {
  const type = Array.isArray(schema.type) ? schema.type[0] : schema.type;
  if (value === null) return Array.isArray(schema.type) && schema.type.includes("null");
  if (schema.enum && !schema.enum.includes(value)) return false;
  switch (type) {
    case "object":
      return (
        typeof value === "object" &&
        !Array.isArray(value) &&
        (schema.required ?? []).every((key) => Object.hasOwn(value, key)) &&
        Object.entries(value).every(
          ([key, entry]) =>
            Object.hasOwn(schema.properties, key) &&
            extractedValueMatches(entry, schema.properties[key]),
        )
      );
    case "array":
      return (
        Array.isArray(value) && value.every((entry) => extractedValueMatches(entry, schema.items))
      );
    case "integer":
      return Number.isSafeInteger(value);
    case "number":
      return Number.isFinite(value);
    default:
      return typeof value === type;
  }
}

const bucket = "YOUR_GCS_BUCKET";
const enableCalls = false;
return [{ json: extractionInput($input.first().json.body, bucket, enableCalls) }];

function checkedImage(bytes, mediaType) {
  const mimeType =
    typeof mediaType === "string" ? mediaType.split(";")[0].trim().toLowerCase() : "";
  if (!bytes || bytes.length < 12 || bytes.length > 2 * 1024 * 1024)
    throw new Error("Image must be at most 2 MiB");
  const ascii = (index, length) => String.fromCharCode(...bytes.subarray(index, index + length));
  if (
    mimeType === "image/png" &&
    bytes.length >= 57 &&
    [137, 80, 78, 71, 13, 10, 26, 10].every((octet, i) => bytes[i] === octet) &&
    ascii(12, 4) === "IHDR"
  ) {
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.length);
    if (view.getUint32(8) === 13 && view.getUint32(16) && view.getUint32(20)) {
      let offset = 33;
      let imageData = false;
      while (offset + 12 <= bytes.length) {
        const length = view.getUint32(offset);
        const type = ascii(offset + 4, 4);
        const end = offset + 12 + length;
        if (end > bytes.length) break;
        if (type === "IDAT" && length > 0) imageData = true;
        if (type === "IEND" && length === 0 && imageData && end === bytes.length) return mimeType;
        offset = end;
      }
    }
  }
  if (
    mimeType === "image/jpeg" &&
    bytes[0] === 0xff &&
    bytes[1] === 0xd8 &&
    bytes[bytes.length - 2] === 0xff &&
    bytes[bytes.length - 1] === 0xd9
  ) {
    let offset = 2;
    let frame = false;
    while (offset + 4 < bytes.length && bytes[offset] === 0xff) {
      while (bytes[offset] === 0xff) offset++;
      const marker = bytes[offset++];
      const length = bytes[offset] * 256 + bytes[offset + 1];
      if (length < 2 || offset + length >= bytes.length - 2) break;
      if (marker >= 0xc0 && marker <= 0xcf && ![0xc4, 0xc8, 0xcc].includes(marker))
        frame = length >= 8;
      if (marker === 0xda && frame && length >= 6) return mimeType;
      offset += length;
    }
  }
  throw new Error("Image bytes do not match a complete PNG or JPEG response");
}

function geminiImageRequest(instruction, schema, mimeType, data) {
  return {
    systemInstruction: { parts: [{ text: instruction }] },
    contents: [
      {
        role: "user",
        parts: [
          { inlineData: { mimeType, data } },
          { text: "Extract the requested fields from the attached image." },
        ],
      },
    ],
    generationConfig: {
      maxOutputTokens: 8192,
      responseMimeType: "application/json",
      responseJsonSchema: schema,
    },
  };
}

const { instruction, schema } = $("Validate image URL and schema").first().json;
const item = $input.first();
if (item.json.statusCode !== 200) throw new Error("Image download must return HTTP 200");
const bytes = await helpers.getBinaryDataBuffer(0, "data");
const mimeType = checkedImage(bytes, item.binary.data.mimeType);
return [
  {
    json: {
      request: geminiImageRequest(
        instruction,
        schema,
        mimeType,
        Buffer.from(bytes).toString("base64"),
      ),
    },
  },
];

function geminiExtractionResult(response, schema) {
  const answer = response?.candidates?.[0];
  if (
    response?.error ||
    response?.promptFeedback?.blockReason ||
    answer?.finishReason !== "STOP" ||
    !Array.isArray(answer.content?.parts)
  )
    throw new Error("Gemini did not complete image extraction");
  const text = answer.content.parts
    .filter((part) => !part?.thought && typeof part?.text === "string")
    .map((part) => part.text)
    .join("");
  let value;
  try {
    value = JSON.parse(text);
  } catch {
    throw new Error("Gemini did not return valid JSON");
  }
  if (!extractedValueMatches(value, schema))
    throw new Error("Gemini JSON does not match the requested fields");
  return { result: JSON.stringify(value) };
}

function extractedValueMatches(value, schema) {
  const type = Array.isArray(schema.type) ? schema.type[0] : schema.type;
  if (value === null) return Array.isArray(schema.type) && schema.type.includes("null");
  if (schema.enum && !schema.enum.includes(value)) return false;
  switch (type) {
    case "object":
      return (
        typeof value === "object" &&
        !Array.isArray(value) &&
        (schema.required ?? []).every((key) => Object.hasOwn(value, key)) &&
        Object.entries(value).every(
          ([key, entry]) =>
            Object.hasOwn(schema.properties, key) &&
            extractedValueMatches(entry, schema.properties[key]),
        )
      );
    case "array":
      return (
        Array.isArray(value) && value.every((entry) => extractedValueMatches(entry, schema.items))
      );
    case "integer":
      return Number.isSafeInteger(value);
    case "number":
      return Number.isFinite(value);
    default:
      return typeof value === type;
  }
}

const { schema } = $("Validate image URL and schema").first().json;
return [{ json: geminiExtractionResult($input.first().json, schema) }];
